-- Publicación editorial autorizada de Fundamentos Institucionales.
-- No afecta otros parámetros, cuentas, documentos ni el programa de Docencia.
DO $$
DECLARE n integer;
BEGIN
 UPDATE public.config_segura
 SET valor='[{"tipo":"introduccion","titulo":"Propósito y sentido de la docencia","subtitulo":"","texto":"La docencia del Tercer Grado encuentra su sentido en una convicción fundamental: **el conocimiento masónico exige comprensión, reflexión y coherencia de conducta**. Desde esta perspectiva, el estudio no persigue la mera acumulación de nociones doctrinales, sino el perfeccionamiento de quien las recibe, interpreta y procura vivir conforme a ellas.\n\nEste espacio surge de la necesidad de fortalecer y dar continuidad a la labor docente del Tercer Grado mediante una plataforma digital de aprendizaje asincrónico, destinada a los Maestros del Taller. Su propósito es facilitar el acceso permanente a los contenidos formativos, permitiendo que cada Hermano pueda estudiarlos, revisarlos y profundizar en ellos de acuerdo con su disponibilidad y ritmo personal, sin las restricciones de un horario común. De este modo, la docencia trasciende las instancias presenciales de formación y encuentra una oportunidad adicional para mantenerse activa en la vida cotidiana del Maestro.\n\nJunto con presentar el sentido y los objetivos de este espacio, compartimos una reflexión sobre los principios y lineamientos generales que deben orientar el estudio y la investigación personal en el Tercer Grado. Esta labor comprende la profundización en sus fundamentos éticos, simbólicos, filosóficos e institucionales, procurando que el conocimiento adquirido no permanezca únicamente en el ámbito intelectual, sino que contribuya al discernimiento, al perfeccionamiento moral y a la práctica consciente de las enseñanzas masónicas.\n\nFinalmente, este espacio aspira a que las reflexiones surgidas del estudio individual encuentren una expresión colectiva en el **Muro Docente**, concebido como un lugar de encuentro e intercambio fraternal. Allí, las distintas perspectivas podrán enriquecer la comprensión de los temas estudiados, fortalecer el diálogo entre Hermanos y contribuir a la construcción de una reflexión compartida que **dé unidad, continuidad y sentido al trabajo docente de la Columna de Maestros**."},{"tipo":"fundamento","titulo":"Naturaleza y sentido de la docencia","subtitulo":"La formación del Maestro como tarea permanente","texto":"La condición de Maestro no señala el término del aprendizaje masónico, sino una responsabilidad más consciente frente a él. Profundizar en los símbolos, el ritual y los deberes de la Maestría supone interrogar su significado, confrontarlo con la propia experiencia y reconocer cuánto resta por perfeccionar en uno mismo.\n\nEste espacio, reservado al trabajo docente de la Cámara de Maestros, acompaña esa labor mediante el estudio personal de los trazados y la reflexión fraterna acerca de su aplicación en la vida dentro y fuera de la Logia. Su soporte digital facilita la continuidad del aprendizaje; **no reemplaza la enseñanza compartida ni el ejercicio personal de la virtud**, sino que constituye un recurso de apoyo que reúne los contenidos docentes y los pone a disposición de cada Maestro para que pueda estudiarlos a su propio tiempo y ritmo.\n\nEl propósito es que cada enseñanza pueda convertirse, progresivamente, en criterio de juicio y orientación para la acción."},{"tipo":"fundamento","titulo":"Propósito formativo y objetivos","subtitulo":"Comprender, discernir y obrar con coherencia","texto":"La docencia procura una comprensión fundada de los contenidos del Tercer Grado y de sus implicancias éticas, filosóficas y simbólicas. Esa comprensión debe favorecer una conciencia esclarecida, capaz de discernir, examinar las propias convicciones y enfrentar con mayor responsabilidad los dilemas que plantea la vida individual y colectiva.\n\nPor ello, el estudio propuesto, las preguntas formativas y la participación en el Muro Docente no constituyen fines en sí mismos: permiten revisar el entendimiento alcanzado, descubrir nuevas interrogantes y elaborar reflexiones que puedan enriquecer el diálogo entre Hermanos.\n\n**El resultado más valioso no es la respuesta acertada, sino la relación honesta entre lo que se comprende, lo que se proclama y lo que se hace.**\n\nLos contenidos de este espacio son elaborados por Maestros de la Logia, procurando mantener su concordancia con el programa de docencia vigente de la Gran Logia de Chile, así como con sus principios y orientaciones formativas."},{"tipo":"fundamento","titulo":"Método de estudio y reflexión","subtitulo":"Tres momentos de una misma labor formativa","texto":"Esta plataforma propone tres momentos complementarios de una misma labor formativa, sin reducir el aprendizaje a una secuencia mecánica:\n\n**a) Lectura comprensiva.** Cada trazado se estudia con atención, buscando comprender sus argumentos, símbolos y enseñanzas esenciales. El tiempo dedicado a la lectura favorece la concentración, pero no sustituye la profundidad de la reflexión.\n\n**b) Evaluación formativa.** Una serie de preguntas invita a revisar la comprensión del tema y a considerar sus implicancias éticas. Su función es favorecer el discernimiento y reconocer los aspectos que requieren mayor estudio, no establecer jerarquías personales entre quienes participan ni distinguir a los Hermanos por la cantidad de respuestas acertadas.\n\n**c) Reflexión y participación.** El Maestro elabora su propia reflexión a partir del trabajo estudiado. Al completar un trabajo conforme a las reglas de la plataforma, puede participar en el **Muro Docente**, donde el intercambio fraternal permite contrastar perspectivas, compartir experiencias y enriquecer el aprendizaje común.\n\nLas tres fases son complementarias: **leer para comprender, examinar para discernir y reflexionar para obrar con mayor conciencia**."},{"tipo":"fundamento","titulo":"El sentido de la Maestría","subtitulo":"La responsabilidad de hacer vida lo aprendido","texto":"La Maestría no se justifica por la sola posesión de un grado. Su valor se manifiesta en la responsabilidad de quien procura ejercerlo con prudencia, rectitud, templanza y espíritu fraternal.\n\nEllo exige una disposición permanente a revisar el propio juicio antes de juzgar al otro, sostener la palabra comprometida, reconocer los errores y actuar con respeto aun frente a la discrepancia.\n\nPor ello, la enseñanza masónica adquiere verdadero significado cuando deja de ser únicamente materia de estudio y se hace reconocible en las relaciones humanas, en el cumplimiento del deber y en la conducta dentro y fuera del Templo.\n\n**La docencia, entonces, no pretende definir al Maestro ideal, sino contribuir al trabajo constante de llegar a serlo.**"},{"tipo":"cierre","titulo":"Invitación a la reflexión","subtitulo":"","texto":"Esperamos que este espacio constituya un aporte significativo a tu formación como Maestro y un estímulo permanente para profundizar en el conocimiento, la reflexión y el perfeccionamiento personal.\n\nQue cada trabajo estudiado sea una oportunidad para examinar nuestras convicciones, enriquecer nuestro discernimiento y fortalecer la coherencia entre lo que pensamos, expresamos y hacemos.\n\n**Te invitamos a compartir con tus Hermanos las reflexiones que surjan de este aprendizaje, contribuyendo así a un diálogo fraterno, respetuoso y enriquecedor, donde el conocimiento compartido fortalezca nuestra labor docente y el compromiso común con los ideales de la Orden.**"}]'
 WHERE clave='doctrina_docencia_maestros';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'Configuración docente ausente o duplicada'; END IF;
 IF (SELECT jsonb_array_length(valor::jsonb) FROM public.config_segura
     WHERE clave='doctrina_docencia_maestros')<>6 THEN
    RAISE EXCEPTION 'No se publicaron los seis bloques editoriales';
 END IF;
END $$;
